        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int[][] intervals = new int[K][2];
        long totalDiff = 0;
        for (int i = 0; i < K; i++) {
            st = new StringTokenizer(br.readLine());
            intervals[i][0] = Integer.parseInt(st.nextToken());
            intervals[i][1] = Integer.parseInt(st.nextToken());
            totalDiff += intervals[i][1] - intervals[i][0];
        }
        int[] dpe = new int[n + 1];
        int[] dpo = new int[n + 1];
        Arrays.fill(dpe, 99999999);
        Arrays.fill(dpo, 99999999);
        if (intervals[0][0] > n) {
            pw.println("Hungry");
            pw.flush();
            return;
        }
        dpe[intervals[0][0]] = 0;
        for (int i = 0; i < K; i++) {
            int[] newDpo = new int[n + 1];
            int[] newDpe = new int[n + 1];
            Arrays.fill(newDpo, 99999999);
            Arrays.fill(newDpe, 99999999);
            Deque<Integer> dq1 = new ArrayDeque<>();
            Deque<Integer> dq2 = new ArrayDeque<>();
            int w = intervals[i][1] - intervals[i][0];
            for (int j = 0; j <= n; j++) {
                while (!dq1.isEmpty() && dpe[dq1.peekLast()] >= dpe[j]) dq1.pollLast();
                while (!dq1.isEmpty() && dq1.peekFirst() < j - w) dq1.pollFirst();
                dq1.offerLast(j);
                newDpo[j] = Math.min(newDpo[j], dpe[dq1.peekFirst()] + 1);
                if (j + w <= n) newDpe[j + w] = Math.min(newDpe[j + w], dpe[j]);
            }
            for (int j = 0; j <= n; j++) {
                while (!dq2.isEmpty() && dpo[dq2.peekLast()] >= dpo[j]) dq2.pollLast();
                while (!dq2.isEmpty() && dq2.peekFirst() < j - w) dq2.pollFirst();
                dq2.offerLast(j);
                newDpe[j] = Math.min(newDpe[j], dpo[dq2.peekFirst()] + 1);
                newDpo[j] = Math.min(newDpo[j], dpo[j]);
            }
            dpo = newDpo;
            dpe = newDpe;
            for (int j = 0; j <= n; j++) {
                dpe[j] = Math.min(dpe[j], dpo[j] + 1);
                dpo[j] = Math.min(dpo[j], dpe[j] + 1);
            }
            int s = (i == K - 1 ? 2 * n : intervals[i + 1][0]) - intervals[i][1];
            for (int j = n; j >= s; j--) {
                dpe[j] = dpe[j - s];
            }
            for (int j = Math.min(n, s - 1); j >= 0; j--) {
                dpe[j] = 99999999;
            }
        }
        int answer = Math.min(dpe[n], dpo[n]);
        if (answer >= 9999999) {
            pw.println("Hungry");
        } else {
            pw.println("Full");
            pw.println(answer);
        }
        pw.flush();
